"""Request handlers."""

from pathlib import Path

from app.services import users

# Root of the sandboxed file area exposed to request handlers.
DATA_DIR = Path(__file__).resolve().parents[2] / "data"


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def handle_list_files(params: dict) -> tuple[int, dict]:
    """List regular files directly inside a directory under ``data/``."""
    raw = params.get("dir", "")
    if not isinstance(raw, str):
        return 400, {"error": "invalid path"}

    segments = raw.split("/") if raw else []
    if any(segment in ("", ".", "..") for segment in segments):
        return 400, {"error": "invalid path"}

    base = DATA_DIR.resolve()
    target = base.joinpath(*segments).resolve()
    if not target.is_relative_to(base):
        return 400, {"error": "invalid path"}
    if not target.is_dir():
        return 404, {"error": "not found"}

    files = sorted(entry.name for entry in target.iterdir() if entry.is_file())
    return 200, {"files": files}
